def compute(vars):
    cib_markets_net_interest_income = vars["v1"]
    managed_net_interest_income = vars["v2"]

    if managed_net_interest_income == 0:
        return {
            "value": None,
            "trace": {
                "cib_markets_net_interest_income": cib_markets_net_interest_income,
                "managed_net_interest_income": managed_net_interest_income,
                "output_meta": {
                    "currency": None,
                    "scale": "ones",
                    "unit": "percentage"
                }
            }
        }

    ratio = cib_markets_net_interest_income / managed_net_interest_income
    percentage = ratio * 100

    return {
        "value": percentage,
        "trace": {
            "cib_markets_net_interest_income": cib_markets_net_interest_income,
            "managed_net_interest_income": managed_net_interest_income,
            "ratio": ratio,
            "output_meta": {
                "currency": None,
                "scale": "ones",
                "unit": "percentage"
            }
        }
    }
